/* SPDX-License-Identifier: Apache-2.0
 *
 * registry_tests — deterministic sponge_wm registry/protocol-state
 * cases. See registry_tests.h.
 *
 * The cases exercise the PRODUCTION model (wm_registry.cc) and the
 * PRODUCTION protocol library (sponge_wm_protocol generators and
 * parsers) together: every published snapshot is generated by the
 * shipped emitter and parsed back by the shipped parser, so a
 * generator/parser misunderstanding cannot self-certify here either —
 * the expected values are transcribed from the binding contracts
 * (docs/plans/phase16-sponge-wm.md §11, docs/05-sponge-de.md §4.6),
 * not captured from this code's own output.
 *
 * Pure and deterministic: no Env, no sessions, no timers, no
 * allocation beyond stack buffers, no globals (all state in the local
 * 'Registry' and 'Ctx').
 */

#include "registry_tests.h"
#include "wm_registry.h"

#include <sponge/wm_protocol.h>
#include <util/string.h>

namespace {

using namespace Sponge::Wm_registry;
using namespace Sponge::Wm_protocol;


struct Ctx
{
	unsigned checks   = 0;
	unsigned failures = 0;
	Check_fn report;

	void check(bool ok, char const *what)
	{
		checks++;
		if (!ok)
			failures++;
		report(ok, what);
	}

	void check_eq(unsigned long got, unsigned long want, char const *what)
	{
		bool const ok = (got == want);
		checks++;
		if (ok) {
			report(true, what);
			return;
		}
		failures++;
		Genode::String<256> const msg(what, ": expected ", want, " got ", got);
		report(false, msg.string());
	}
};


/* Generate an XML document into 'buf' (see wm_protocol_probe). */
template <typename FN>
char const *gen_xml(char *buf, Genode::size_t buf_len,
                    char const *type, FN const &fn)
{
	auto const res = Genode::Xml_generator::generate({ buf, buf_len }, type, fn);

	if (res.failed()) {
		buf[0] = '\0';
		return buf;
	}
	return buf;
}


Genode::Node node_of(char const *bytes, Genode::size_t len)
{
	return Genode::Node(Genode::Const_byte_range_ptr(bytes, len));
}


Genode::Node node_of(char const *nul_terminated)
{
	return node_of(nul_terminated, Genode::strlen(nul_terminated));
}


/* ==================== 1. lifecycle / identity =================== */

void case_lifecycle(Ctx &c)
{
	Registry reg;

	unsigned long const w1 = reg.create_window("sponge-de -> Sponge DE Demo");
	unsigned long const w2 = reg.create_window("pkg_runtime -> pkg_gui_demo");
	unsigned long const w3 = reg.create_window("pkg_runtime -> terminal");

	c.check(w1 != 0 && w2 != 0 && w3 != 0, "lifecycle: windows created");
	c.check_eq(w2, w1 + 1, "lifecycle: wid monotonic (2 == 1+1)");
	c.check_eq(w3, w1 + 2, "lifecycle: wid monotonic (3 == 1+2)");
	c.check_eq(reg.count(), 3, "lifecycle: count == 3");

	c.check(reg.find(w2) != nullptr, "lifecycle: find(wid) present");
	c.check_eq(reg.find(w2)->wid, w2, "lifecycle: find() returns the same wid");

	Window const *by_label = reg.by_label("pkg_runtime -> terminal");
	c.check(by_label != nullptr && by_label->wid == w3,
	        "lifecycle: by_label resolves the exact identity");

	c.check(reg.by_label("pkg_runtime -> term") == nullptr,
	        "lifecycle: by_label is exact (no prefix match)");
	c.check(reg.by_label("") == nullptr,
	        "lifecycle: by_label rejects empty identity");

	Dirty const d = reg.destroy_window(w2);
	c.check(dirty_any(d, Dirty::WINDOW_LIST),
	        "lifecycle: destroy dirties window_list");
	c.check(dirty_any(d, Dirty::CHROME),
	        "lifecycle: destroy dirties window_chrome (absence = destroy)");
	c.check(reg.find(w2) == nullptr, "lifecycle: destroyed wid is gone");
	c.check_eq(reg.count(), 2, "lifecycle: count decremented");

	c.check(reg.destroy_window(w2) == Dirty::NONE,
	        "lifecycle: destroying an unknown wid is a no-op");

	/* table exhaustion: fill the remaining slots, then expect 0 */
	unsigned long last = 0;
	for (unsigned i = 0; i < MAX_WINDOWS + 8; i++) {
		last = reg.create_window("filler");
		if (last == 0)
			break;
	}
	c.check_eq(last, 0, "lifecycle: create_window reports table exhaustion");
}


/* ================= 2. window_list snapshot (v1) ================= */

void case_window_list(Ctx &c)
{
	Registry reg;

	unsigned long const w = reg.create_window("sponge-de -> Sponge DE Demo");
	reg.set_title(w, "Sponge DE Demo");
	reg.set_client_geometry(w, 50, 60, 640, 480);
	reg.set_has_alpha(w, true);
	reg.set_resizeable(w, true);

	/* unsized window: must be omitted from the report */
	unsigned long const u = reg.create_window("sponge-de -> QGenodeScreen");

	char buf[2048];
	char const *xml = gen_xml(buf, sizeof(buf), "window_list",
	                         [&] (Genode::Xml_generator &g) {
		                         reg.gen_window_list(g); });

	unsigned num = 0;
	Window_list_entry got { };
	bool root_ok = parse_window_list(node_of(xml),
		[&] (Window_list_entry const &e) {
			num++;
			got = e;
		});

	c.check(root_ok, "window_list: root is <window_list>");
	c.check_eq(num, 1, "window_list: exactly one entry (unsized omitted)");
	c.check_eq(got.id, w, "window_list: id == core-assigned wid");
	c.check(Genode::strcmp(got.label.string(),
	                       "sponge-de -> Sponge DE Demo") == 0,
	        "window_list: full session label preserved");
	c.check(Genode::strcmp(got.title.string(), "Sponge DE Demo") == 0,
	        "window_list: client title preserved");
	c.check_eq((unsigned long)got.width,  640, "window_list: width == client width");
	c.check_eq((unsigned long)got.height, 480, "window_list: height == client height");
	c.check(got.has_alpha,  "window_list: has_alpha emitted when true");
	c.check(got.resizeable, "window_list: resizeable emitted when true");
	c.check(!got.hidden,    "window_list: hidden stays false (v1.1 parking convention)");

	/* sizing the second window makes it appear */
	reg.set_client_geometry(u, 0, 0, 1024, 768);
	xml = gen_xml(buf, sizeof(buf), "window_list",
	              [&] (Genode::Xml_generator &g) { reg.gen_window_list(g); });
	num = 0;
	parse_window_list(node_of(xml),
		[&] (Window_list_entry const &) { num++; });
	c.check_eq(num, 2, "window_list: sized window appears");

	/* entry order is table (creation) order */
	unsigned long first_id = 0;
	parse_window_list(node_of(xml),
		[&] (Window_list_entry const &e) {
			if (first_id == 0)
				first_id = e.id;
		});
	c.check_eq(first_id, w, "window_list: creation order kept");
}


/* ============ 3. dirty flags drive report republication ========== */

void case_dirty_flags(Ctx &c)
{
	Registry reg;
	unsigned long const w = reg.create_window("a -> b");
	reg.set_client_geometry(w, 10, 20, 300, 200);

	Dirty const title_dirty = reg.set_title(w, "title");
	c.check(dirty_any(title_dirty, Dirty::WINDOW_LIST)
	     && dirty_any(title_dirty, Dirty::CHROME),
	        "dirty: title change dirties window_list and window_chrome");
	c.check(reg.set_title(w, "title") == Dirty::NONE,
	        "dirty: unchanged title is a no-op");

	c.check(reg.set_client_geometry(w, 11, 21, 300, 200) == Dirty::NONE,
	        "dirty: client move is a no-op for reports");
	c.check(dirty_any(reg.set_client_geometry(w, 11, 21, 320, 200),
	                  Dirty::WINDOW_LIST),
	        "dirty: client size change dirties window_list");
	c.check(dirty_any(reg.set_client_geometry(w, 11, 21, 320, 200),
	                  Dirty::CHROME) == false,
	        "dirty: client size change alone is not a chrome change (size check)");

	/* while unplaced, the transient inner rect follows the client rect */
	Registry reg2;
	unsigned long const v = reg2.create_window("a -> c");
	Dirty const d = reg2.set_client_geometry(v, 0, 0, 100, 100);
	c.check(dirty_any(d, Dirty::WINDOW_LIST) && dirty_any(d, Dirty::CHROME),
	        "dirty: first sizing of an unplaced window also dirties chrome");

	c.check(dirty_any(reg.set_has_alpha(w, true), Dirty::WINDOW_LIST),
	        "dirty: has_alpha change dirties window_list");
	c.check(reg.set_has_alpha(w, true) == Dirty::NONE,
	        "dirty: unchanged has_alpha is a no-op");

	Dirty const r = reg.set_resizeable(w, true);
	c.check(dirty_any(r, Dirty::WINDOW_LIST) && dirty_any(r, Dirty::CHROME),
	        "dirty: resizeable change dirties window_list and window_chrome");
}


/* ============ 4. window_request: placement + sticky close ========= */

void case_window_request(Ctx &c)
{
	Registry reg;
	unsigned long const w = reg.create_window("a -> b");
	reg.set_client_geometry(w, 10, 20, 640, 480);

	/* first placement: SIZE arrives -> chrome change */
	c.check(dirty_any(reg.place(w, 192, 172, 640, 480), Dirty::CHROME),
	        "window_request: first placement dirties chrome (size)");

	/* pure move: never a chrome publication (v1.1: "not move") */
	c.check(reg.place(w, 292, 272, 640, 480) == Dirty::NONE,
	        "window_request: move does not dirty any report");

	/* size change: chrome publication */
	c.check(dirty_any(reg.place(w, 292, 272, 800, 600), Dirty::CHROME),
	        "window_request: size change dirties chrome");

	/* unknown wid: no-op */
	c.check(reg.place(9999, 0, 0, 10, 10) == Dirty::NONE,
	        "window_request: unknown wid placement is a no-op");

	Rect const inner = reg.inner_rect(w);
	c.check(inner.x == 292 && inner.y == 272
	     && inner.w == 800 && inner.h == 600,
	        "window_request: inner rect follows the placement");

	/* parked placement is applied verbatim (no model special-case) */
	reg.place(w, -32000, -32000, 800, 600);
	Rect const parked = reg.inner_rect(w);
	c.check(parked.x == -32000 && parked.y == -32000,
	        "window_request: parking sentinel placement round-trips");
	reg.place(w, 292, 272, 800, 600);

	/* sticky close: owed exactly once, sticky until the wid vanishes */
	c.check(reg.request_close(w),
	        "window_request: close applies the app-visible 0x0 convention once");
	c.check(!reg.request_close(w),
	        "window_request: close is sticky (re-processing is a no-op)");
	c.check(reg.find(w)->close_requested,
	        "window_request: close_requested stays latched");
	c.check(reg.find(w)->close_applied,
	        "window_request: close_applied records the owed convention");

	/* the sticky node ends with the wid */
	reg.destroy_window(w);
	c.check(!reg.request_close(w),
	        "window_request: close for a vanished wid is a no-op");
}


/* ====================== 5. focus truth ========================== */

void case_focus(Ctx &c)
{
	Registry reg;
	unsigned long const w1 = reg.create_window("a -> one");
	unsigned long const w2 = reg.create_window("a -> two");

	Focus_target t1 { true, w1 };
	c.check(dirty_any(reg.set_focus(t1), Dirty::FOCUS),
	        "focus: steering to a window dirties focus_state");
	c.check(reg.set_focus(t1) == Dirty::NONE,
	        "focus: unchanged truth is a no-op");
	c.check(reg.focus().set && reg.focus().wid == w1,
	        "focus: truth records the steered wid");

	/* content-click truth uses the same setter */
	Focus_target t2 { true, w2 };
	c.check(dirty_any(reg.set_focus(t2), Dirty::FOCUS),
	        "focus: content click also updates the truth");
	c.check_eq(reg.focus().wid, w2, "focus: truth follows the click");

	/* steering to an unknown wid normalizes to 'no focus' */
	Focus_target tbad { true, 9999 };
	c.check(dirty_any(reg.set_focus(tbad), Dirty::FOCUS),
	        "focus: unknown wid steering clears the truth");
	c.check(!reg.focus().set, "focus: truth is the empty target");

	/* destroying the focused window clears the truth */
	reg.set_focus(t1);
	Dirty const d = reg.destroy_window(w1);
	c.check(dirty_any(d, Dirty::FOCUS),
	        "focus: destroying the focused window dirties focus_state");
	c.check(!reg.focus().set, "focus: truth cleared on window removal");

	/* snapshot round-trip (production generator + production parser) */
	reg.set_focus(t2);
	char buf[512];
	char const *xml = gen_xml(buf, sizeof(buf), "focus_state",
	                         [&] (Genode::Xml_generator &g) {
		                         reg.gen_focus_state(g); });
	Focus_target got { false, 0 };
	c.check(parse_focus_state(node_of(xml), got),
	        "focus: focus_state snapshot parses");
	c.check(got.set && got.wid == w2,
	        "focus: focus_state snapshot carries the truth wid");

	reg.set_focus(Focus_target { });
	xml = gen_xml(buf, sizeof(buf), "focus_state",
	              [&] (Genode::Xml_generator &g) { reg.gen_focus_state(g); });
	c.check(parse_focus_state(node_of(xml), got) && !got.set,
	        "focus: empty root reads as no focus");
}


/* ============ 6. margins + window_chrome snapshot (v1.1) ========= */

void case_chrome(Ctx &c)
{
	Registry reg;

	Margins const m { 20, 8, 2, 2 };
	c.check(dirty_any(reg.set_margins(m), Dirty::CHROME),
	        "chrome: margins change dirties window_chrome");
	c.check(reg.set_margins(m) == Dirty::NONE,
	        "chrome: unchanged margins are a no-op");

	unsigned long const w = reg.create_window("sponge-de -> Sponge DE Demo");
	reg.set_title(w, "Sponge DE Demo");
	reg.set_client_geometry(w, 100, 100, 640, 480);
	reg.set_resizeable(w, true);

	char buf[2048];
	char const *xml = gen_xml(buf, sizeof(buf), "window_chrome",
	                         [&] (Genode::Xml_generator &g) {
		                         reg.gen_window_chrome(g); });

	unsigned num = 0;
	Window_chrome got { };
	c.check(parse_window_chrome(node_of(xml),
		[&] (Window_chrome const &ch) { num++; got = ch; }),
	        "chrome: window_chrome snapshot parses");
	c.check_eq(num, 1, "chrome: one entry for one sized window");
	c.check_eq(got.wid, w, "chrome: entry keyed by the core wid");
	c.check(Genode::strcmp(got.label.string(),
	                       "sponge-de -> Sponge DE Demo") == 0,
	        "chrome: label carried");
	c.check(Genode::strcmp(got.title.string(), "Sponge DE Demo") == 0,
	        "chrome: title carried");
	c.check(got.resizeable, "chrome: resizeable carried");

	/* unplaced: outer == client rect expanded by the margins */
	Rect const outer = outer_from_inner(Rect { 100, 100, 640, 480 }, m);
	c.check_eq((unsigned long)got.fw, (unsigned long)outer.w,
	           "chrome: fw == outer width (client rect + margins)");
	c.check_eq((unsigned long)got.fh, (unsigned long)outer.h,
	           "chrome: fh == outer height (client rect + margins)");

	/* placed: outer == placement expanded by the margins */
	reg.place(w, 192, 172, 800, 600);
	xml = gen_xml(buf, sizeof(buf), "window_chrome",
	              [&] (Genode::Xml_generator &g) { reg.gen_window_chrome(g); });
	parse_window_chrome(node_of(xml),
		[&] (Window_chrome const &ch) { got = ch; });
	Rect const placed_outer = outer_from_inner(Rect { 192, 172, 800, 600 }, m);
	c.check_eq((unsigned long)got.fw, (unsigned long)placed_outer.w,
	           "chrome: fw follows the placement size");
	c.check_eq((unsigned long)got.fh, (unsigned long)placed_outer.h,
	           "chrome: fh follows the placement size");

	/* destroy: absence from the snapshot IS the destroy publication */
	reg.destroy_window(w);
	xml = gen_xml(buf, sizeof(buf), "window_chrome",
	              [&] (Genode::Xml_generator &g) { reg.gen_window_chrome(g); });
	num = 0;
	parse_window_chrome(node_of(xml),
		[&] (Window_chrome const &) { num++; });
	c.check_eq(num, 0, "chrome: destroyed window is absent from the snapshot");

	/* unsized windows carry no chrome */
	reg.create_window("a -> unsized");
	xml = gen_xml(buf, sizeof(buf), "window_chrome",
	              [&] (Genode::Xml_generator &g) { reg.gen_window_chrome(g); });
	parse_window_chrome(node_of(xml),
		[&] (Window_chrome const &) { num++; });
	c.check_eq(num, 0, "chrome: unsized windows are not published");
}


/* ============ 7. chrome-view association (wid <--> title) ======== */

void case_chrome_assoc(Ctx &c)
{
	Registry reg;
	unsigned long const w = reg.create_window("a -> b");

	Genode::String<32> const title = view_title(w);
	unsigned long back = 0;
	c.check(parse_view_title(title.string(), back) && back == w,
	        "assoc: view_title/parse_view_title round-trips the wid");

	c.check(!parse_view_title("5x", back),
	        "assoc: non-canonical titles are rejected");
	c.check(!parse_view_title("", back),
	        "assoc: empty titles are rejected");

	c.check(reg.attach_chrome(w), "assoc: attach resolves the wid");
	c.check(reg.find(w)->chrome_present, "assoc: attach recorded");
	c.check(reg.detach_chrome(w), "assoc: detach resolves the wid");
	c.check(!reg.find(w)->chrome_present, "assoc: detach recorded");
	c.check(!reg.attach_chrome(9999),
	        "assoc: attach for an unknown wid fails");
}


/* ============ 8. inner/outer math + resize request ============== */

void case_geometry(Ctx &c)
{
	Registry reg;
	Margins const m { 20, 8, 2, 2 };
	reg.set_margins(m);

	unsigned long const w = reg.create_window("a -> b");
	reg.set_client_geometry(w, 10, 20, 300, 200);

	long rw = 0, rh = 0;
	reg.requested_size(w, rw, rh);
	c.check(rw == 300 && rh == 200,
	        "geometry: unplaced resize request is the client size");

	Rect const unplaced = reg.inner_rect(w);
	c.check(unplaced.x == 10 && unplaced.y == 20
	     && unplaced.w == 300 && unplaced.h == 200,
	        "geometry: unplaced inner rect is the client rect");

	reg.place(w, 100, 200, 400, 300);
	reg.requested_size(w, rw, rh);
	c.check(rw == 400 && rh == 300,
	        "geometry: placed resize request is the placement size");

	Rect const inner = reg.inner_rect(w);
	Rect const outer = reg.outer_rect(w);
	c.check(outer.x == inner.x - m.left && outer.y == inner.y - m.top
	     && outer.w == inner.w + m.left + m.right
	     && outer.h == inner.h + m.top + m.bottom,
	        "geometry: outer == inner expanded by the margins");

	Rect const round_trip = inner_from_outer(outer, m);
	c.check(round_trip.x == inner.x && round_trip.y == inner.y
	     && round_trip.w == inner.w && round_trip.h == inner.h,
	        "geometry: inner_from_outer inverts outer_from_inner");

	reg.destroy_window(w);
	reg.requested_size(w, rw, rh);
	c.check(rw == 0 && rh == 0,
	        "geometry: request for a vanished wid is zero-sized");
}


}  /* anonymous namespace */


unsigned Sponge::Wm_registry::run_registry_tests(Check_fn report)
{
	Ctx c { };
	c.report = report;

	case_lifecycle(c);
	case_window_list(c);
	case_dirty_flags(c);
	case_window_request(c);
	case_focus(c);
	case_chrome(c);
	case_chrome_assoc(c);
	case_geometry(c);

	return c.failures;
}
